  'Ranger|Male|Short': 'data:image/webp;base64,',
  'Ranger|Male|Short+beard': 'data:image/webp;base64,',
  'Ranger|Male|Long': 'data:image/webp;base64,',
  'Ranger|Female|Long': 'data:image/webp;base64,',
  'Ranger|Female|Ponytail': 'data:image/webp;base64,',
  'Ranger|Female|Bun': 'data:image/webp;base64,',
  'Spellweaver|Male|Short': 'data:image/webp;base64,',
