const BACKGROUNDS: Record<string, string> = {
  'Guardian': 'data:image/webp;base64,',
  'Ranger': 'data:image/webp;base64,',
  'Spellweaver': 'data:image/webp;base64,',
};

export const BACKGROUND_ASPECT: Record<string, string> = {
  Guardian: '1920 / 1280',
  Ranger: '1472 / 1408',
  Spellweaver: '1472 / 1408',
};

export const GENERATED_COMBOS: { classId: GuardianState['classId']; look: 'Female' | 'Male'; hair: string; label: string }[] = [
  { classId: 'Guardian', look: 'Male', hair: 'Short', label: 'Guardian · Male · Short' },
  { classId: 'Guardian', look: 'Male', hair: 'Short+beard', label: 'Guardian · Male · Short+beard' },
  { classId: 'Guardian', look: 'Male', hair: 'Bald', label: 'Guardian · Male · Bald' },
  { classId: 'Guardian', look: 'Female', hair: 'Long', label: 'Guardian · Female · Long' },
  { classId: 'Guardian', look: 'Female', hair: 'Ponytail', label: 'Guardian · Female · Ponytail' },
  { classId: 'Guardian', look: 'Female', hair: 'Braided', label: 'Guardian · Female · Braided' },
  { classId: 'Ranger', look: 'Male', hair: 'Short', label: 'Ranger · Male · Short' },
  { classId: 'Ranger', look: 'Male', hair: 'Short+beard', label: 'Ranger · Male · Short+beard' },
  { classId: 'Ranger', look: 'Male', hair: 'Long', label: 'Ranger · Male · Long' },
  { classId: 'Ranger', look: 'Female', hair: 'Long', label: 'Ranger · Female · Long' },
  { classId: 'Ranger', look: 'Female', hair: 'Ponytail', label: 'Ranger · Female · Ponytail' },
  { classId: 'Ranger', look: 'Female', hair: 'Bun', label: 'Ranger · Female · Bun' },
  { classId: 'Spellweaver', look: 'Male', hair: 'Short', label: 'Spellweaver · Male · Short' },
  { classId: 'Spellweaver', look: 'Male', hair: 'Bald', label: 'Spellweaver · Male · Bald' },
  { classId: 'Spellweaver', look: 'Male', hair: 'Long', label: 'Spellweaver · Male · Long' },
  { classId: 'Spellweaver', look: 'Female', hair: 'Long', label: 'Spellweaver · Female · Long' },
  { classId: 'Spellweaver', look: 'Female', hair: 'Braided', label: 'Spellweaver · Female · Braided' },
  { classId: 'Spellweaver', look: 'Female', hair: 'Bun', label: 'Spellweaver · Female · Bun' },
];

function comboKey(g: GuardianState | null | undefined): string | null {
  if (!g) return null;
  return `${g.classId}|${g.look}|${g.hair}`;
}

export function generatedFigureFor(g: GuardianState | null | undefined): string | null {
  const k = comboKey(g);
  return k ? FIGURES[k] || null : null;
}

export function generatedBackgroundFor(g: GuardianState | null | undefined): string | null {
  if (!g) return null;
  return BACKGROUNDS[g.classId] || null;
}

export function generatedImageFor(g: GuardianState | null | undefined): string | null {
  return generatedFigureFor(g);
}

export function generatedLabelFor(g: GuardianState | null | undefined): string | null {
  const k = comboKey(g);
  if (!k) return null;
  const hit = GENERATED_COMBOS.find((c) => `${c.classId}|${c.look}|${c.hair}` === k);
  return hit ? hit.label : null;
}
